/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">main</param>
public static void main(Args _args)
{
    AVASalesQuotationController_SSRSPrintInMemory salesQuotationController_SSRSPrintInMemory = AVASalesQuotationController_SSRSPrintInMemory::construct();


    salesQuotationController_SSRSPrintInMemory.initArgs(_args, PrintMgmtDocType::construct(PrintMgmtDocumentType::Quotation).getDefaultReportFormat());
    salesQuotationController_SSRSPrintInMemory.parmavaPrintInMemory(NoYes::Yes);
    salesQuotationController_SSRSPrintInMemory.parmAVAReportRecord(_args.record());

    salesQuotationController_SSRSPrintInMemory.startOperation();
}

/// <summary>
