/// <summary>
/// designed from AVA
/// </summary>
protected void initFormLetterReport()
{
    CustQuotationJour   loccustQuotationJour;
    if (args.dataset() == tableNum(CustQuotationJour))
    {
        loccustQuotationJour = args.record();
    }
    super();
    formLetterReport.parmUsePrintMgmtDestinations(false);
    SrsReportDataContract       locreportContract = this.parmReportContract();
    SRSPrintDestinationSettings printerSettings = locreportContract.parmPrintSettings();
    printerSettings.printMediumType(SRSPrintMediumType::File);
    printerSettings.fileFormat(SRSReportFileFormat::PDF);
    printerSettings.fileName(strfmt("%1 : &2",loccustQuotationJour.QuotationDocNum,date2Str(loccustQuotationJour.QuotationDate,123,2,2,2,2,2,2)));



    formLetterReport.parmDefaultCopyPrintJobSettings(printerSettings);
    formLetterReport.parmDefaultOriginalPrintJobSettings(printerSettings);
    locreportContract.parmPrintSettings(printerSettings);
}
